using DarkFantasyMerchant.Core;
using DarkFantasyMerchant.Game;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;

namespace DarkFantasyMerchant.Tests.EditMode
{
    /// <summary>Checks the city view content generated by the world map setup tool.</summary>
    public class CityViewContentTests
    {
        private const string EconomyPath = "Assets/Data/Economy/Economy.asset";
        private const string BuildingsPath = "Assets/Data/Buildings/Buildings.asset";
        private const string MapPath = "Assets/Data/WorldMap/WorldMap.asset";

        private static T Load<T>(string path) where T : Object
        {
            var asset = AssetDatabase.LoadAssetAtPath<T>(path);
            Assert.IsNotNull(asset, path);
            return asset;
        }

        [Test]
        public void EveryActiveCity_HasAUsableGrid()
        {
            var buildings = Load<BuildingsDefinition>(BuildingsPath);

            foreach (MapCity entry in Load<WorldMapDefinition>(MapPath).MapCities)
            {
                if (!entry.Active)
                {
                    continue;
                }

                Assert.IsNotNull(entry.City.Layout, entry.City.name);
                Assert.IsTrue(entry.City.Layout.TryCreateGrid(buildings, out _, out string problem), $"{entry.City.name}: {problem}");
            }
        }

        [Test]
        public void EveryCity_StartsWithTheHousesItsPopulationNeeds()
        {
            var buildings = Load<BuildingsDefinition>(BuildingsPath);
            var economy = Load<EconomyDefinition>(EconomyPath);
            int roomPerHouse = buildings.House.Room;

            foreach (MapCity entry in Load<WorldMapDefinition>(MapPath).MapCities)
            {
                if (!entry.Active)
                {
                    continue;
                }

                Assert.IsNotNull(entry.City.Layout, entry.City.name);
                Assert.IsTrue(entry.City.Layout.TryCreateGrid(buildings, out CityGrid grid, out string problem), $"{entry.City.name}: {problem}");
                int needed = economy.StartingRoomOf(entry.City, roomPerHouse);

                // Just the houses the starting housed need, all connected.
                Assert.AreEqual(needed / roomPerHouse, grid.CountConnectedHouses(), entry.City.name);
                Assert.AreEqual(grid.CountHouses(), grid.CountConnectedHouses(), entry.City.name);
            }
        }

        [Test]
        public void EveryLayout_HasATownHall()
        {
            foreach (string guid in AssetDatabase.FindAssets("t:" + nameof(CityLayoutDefinition), new[] { "Assets/Data/CityLayouts" }))
            {
                var layout = AssetDatabase.LoadAssetAtPath<CityLayoutDefinition>(AssetDatabase.GUIDToAssetPath(guid));

                Assert.IsTrue(layout.HasTownHall, layout.name);
            }
        }

        [Test]
        public void EveryLayout_HasAPort()
        {
            foreach (string guid in AssetDatabase.FindAssets("t:" + nameof(CityLayoutDefinition), new[] { "Assets/Data/CityLayouts" }))
            {
                var layout = AssetDatabase.LoadAssetAtPath<CityLayoutDefinition>(AssetDatabase.GUIDToAssetPath(guid));

                Assert.IsTrue(layout.HasPort, layout.name);
            }
        }

        // The layouts are connected for either contact: by sides, which also holds with corners.
        [TestCase(RoadContact.SidesAndCorners)]
        [TestCase(RoadContact.SidesOnly)]
        public void EveryStartingHouse_IsConnected(RoadContact contact)
        {
            BuildingsDefinition buildings = Object.Instantiate(Load<BuildingsDefinition>(BuildingsPath));

            try
            {
                TestBuildings.SetRoadContact(buildings, contact);

                foreach (MapCity entry in Load<WorldMapDefinition>(MapPath).MapCities)
                {
                    if (!entry.Active)
                    {
                        continue;
                    }

                    Assert.IsTrue(entry.City.Layout.TryCreateGrid(buildings, out CityGrid grid, out string problem), $"{entry.City.name}: {problem}");
                    Assert.AreEqual(contact, grid.Contact);

                    foreach (PlacedBuilding building in grid.Buildings)
                    {
                        if (building.Kind.IsHouse)
                        {
                            Assert.IsTrue(
                                building.IsConnected,
                                $"{entry.City.name}: the house at {building.Place.Origin}");
                        }
                    }
                }
            }
            finally
            {
                Object.DestroyImmediate(buildings);
            }
        }

        [Test]
        public void TheHouses_Are2x1_AndTheWorkshops2x2()
        {
            var buildings = Load<BuildingsDefinition>(BuildingsPath);

            Assert.AreEqual(new Vector2Int(2, 1), buildings.House.FootprintSize, buildings.House.name);

            foreach (WorkshopDefinition workshop in buildings.Workshops)
            {
                Assert.AreEqual(new Vector2Int(2, 2), workshop.FootprintSize, workshop.name);
            }
        }

        [Test]
        public void TheCatalogue_PlacesAlongTheRoads()
        {
            Assert.IsInstanceOf<RoadsidePlacementDefinition>(Load<BuildingsDefinition>(BuildingsPath).PlacementStrategy);
        }
    }
}
